// Golden compatibility tests: the TS sync / view cleanup must leave exactly the view trees and state files the Python
// CLI (hf-xfer) leaves for the same inputs. The expected files are generated by scripts/golden/generate.sh, run by a
// person who has the CLI installed, and then checked in. Without them the cases are reported as skipped.
// A mismatch is a compatibility bug to fix in src/core, never something to re-baseline.
import { createHash } from 'node:crypto';
import { existsSync, lstatSync, mkdirSync, readFileSync, readlinkSync, realpathSync, renameSync, symlinkSync, unlinkSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { beforeEach, describe, expect, it } from 'vitest';
import { pyDumpsCompact, pyDumpsDefault, pyDumpsIndent1, pyLoads, pyQuote } from '../../src/core/compat/pyjson';
import { AppLock } from '../../src/core/exec/lock';
import { executeSync, planSync } from '../../src/core/sync/sync';
import { createViewImpactProvider } from '../../src/core/views/impact';
import { useCanaries } from '../helpers/canary';
import { applyViewOps, doomRepo, loadCase, type CaseSpec, type FetchFn } from '../core/views/_case';
import { buildCase } from './build-fixture.mjs';
import { maskedState, treeListing } from './tree-listing';
import { tempDir } from '../core/_temp';


useCanaries();
beforeEach(() => expect.hasAssertions());

const here = path.dirname(fileURLToPath(import.meta.url));
const cases = ['sync-fresh', 'sync-registry', 'sync-adopt', 'delete-repo', 'lmstudio-collision'];
type ViewName = 'lmstudio' | 'ollama';
const noNetwork: FetchFn = () => Promise.reject(new Error('golden tests never touch the network'));

const readCase = (name: string): CaseSpec => JSON.parse(readFileSync(path.join(here, 'cases', name, 'case.json'), 'utf8')) as CaseSpec;
const read = (...p: string[]): string => readFileSync(path.join(here, ...p), 'utf8');

type Loaded = Awaited<ReturnType<typeof loadCase>>;

/** One sync under the app lock, exactly as the CLI would be asked to: execute, offline, no mass-removal override. */
async function sync(l: Loaded, views: readonly ViewName[]): Promise<void> {
  const plan = await planSync(l.config, l.model, { offline: true, now: 0 });
  const result = await executeSync(plan, {
    safeFs: l.safeFs, fs: l.fs, fetch: noNetwork, allowMassRemoval: false, token: null, now: () => new Date(0),
    lock: new AppLock(path.join(path.dirname(l.c.hub), '.hf-cache-manager')),
  });
  expect(result.views.map((v) => [v.view, v.status])).toEqual(views.map((v) => [v, 'applied']));
}

function expectViews(l: Loaded, views: readonly ViewName[], expectedDir: string, step: string): void {
  const hubReal = realpathSync(l.c.hub);
  const caseDir = realpathSync(l.c.dir);
  for (const v of views) {
    const root = realpathSync(l.c[v]!);
    expect(treeListing(root, hubReal, caseDir), `${v} tree after ${step}`).toBe(readFileSync(path.join(expectedDir, step, `${v}.tree`), 'utf8'));
    expect(maskedState(root), `${v} state after ${step}`).toBe(readFileSync(path.join(expectedDir, step, `${v}.state.json`), 'utf8'));
  }
}

for (const name of cases) {
  const exp = path.join(here, 'cases', name, 'expected');
  describe.runIf(existsSync(exp))(`golden: ${name}`, () => {
    it("TS sync produces the CLI's view trees and state files byte-for-byte", async () => {
      const spec = readCase(name);
      const views = spec.views;
      const l = await loadCase(spec);
      await sync(l, views);
      expectViews(l, views, exp, 'after-sync');
      if (name === 'sync-adopt') {
        for (const v of views) unlinkSync(path.join(l.c[v]!, '.hfhub-state.json'));
        await sync(l, views);
        expectViews(l, views, exp, 'after-adopt');
      }
      if (name === 'delete-repo') {
        const { ops } = await createViewImpactProvider(l.config, l.fs).impactFor(l.model, doomRepo(l.model, 'acme/Tiny-GGUF'));
        await applyViewOps(ops, l.safeFs);
        mkdirSync(path.join(l.c.dir, 'moved'));
        renameSync(path.join(l.c.hub, 'models--acme--Tiny-GGUF'), path.join(l.c.dir, 'moved', 'models--acme--Tiny-GGUF'));
        expectViews(l, views, exp, 'after-delete');
      }
    });
  });
  if (!existsSync(exp)) {
    describe(`golden: ${name}`, () => {
      it.skip('fixtures absent — run scripts/golden/generate.sh (needs the Python hf-xfer CLI)', () => {});
    });
  }
}

interface PyVectors { json: Array<{ indent1: string; compact: string; default: string }>; quote: string[] }
const expectedJson = path.join(here, 'pyjson', 'expected.json');
describe.runIf(existsSync(expectedJson))('golden: pyjson', () => {
  it('pyDumps* and pyQuote match CPython for every vector', () => {
    const inputs = JSON.parse(read('pyjson', 'inputs.json')) as { json: string[]; quote: string[] };
    const expected = JSON.parse(readFileSync(expectedJson, 'utf8')) as PyVectors;
    expect(expected.json).toHaveLength(inputs.json.length);
    expect(expected.quote).toHaveLength(inputs.quote.length);
    inputs.json.forEach((text, i) => {
      const v = pyLoads(text);
      expect(pyDumpsIndent1(v), `indent=1 of ${text}`).toBe(expected.json[i]!.indent1);
      expect(pyDumpsCompact(v), `compact of ${text}`).toBe(expected.json[i]!.compact);
      expect(pyDumpsDefault(v), `default of ${text}`).toBe(expected.json[i]!.default);
    });
    inputs.quote.forEach((s, i) => expect(pyQuote(s), `quote of ${JSON.stringify(s)}`).toBe(expected.quote[i]));
  });
});
if (!existsSync(expectedJson)) {
  describe('golden: pyjson', () => {
    it.skip('fixtures absent — run scripts/golden/generate.sh (needs the Python hf-xfer CLI)', () => {});
  });
}

// ---- Checks that run everywhere: the pieces the golden comparison stands on ----
describe('golden inputs', () => {
  it('every case builds, and the listing of a fresh case is stable and ordered by UTF-8 bytes', async () => {
    for (const name of cases) {
      const dir = await tempDir();
      const built = await buildCase(dir, readCase(name));
      const hub = realpathSync(built.hub);
      const first = treeListing(hub, hub, dir);
      expect(first).toBe(treeListing(hub, hub, dir));
      expect(first.endsWith('\n')).toBe(true);
      const rels = first.trimEnd().split('\n').map((l) => l.split('\t')[0]!);
      const bytes = rels.map((r) => Buffer.from(r, 'utf8'));
      expect(bytes.every((b, i) => i === 0 || Buffer.compare(bytes[i - 1]!, b) < 0)).toBe(true);
    }
  });

  it('sync-fresh holds the shapes the brief lists (dangling current link with an older fallback, no basename collision, shards, drafts)', () => {
    const spec = readCase('sync-fresh');
    const files = spec.repos[0]!.snapshots.flatMap((s) => s.files.map((f) => ({ commit: s.commit, ...f })));
    expect(files.find((f) => f.path === 'Tiny-Q6_K.gguf' && f.commit === 'c2')?.dangling).toBe(true);
    expect(files.find((f) => f.path === 'Tiny-Q6_K.gguf' && f.commit === 'c1')?.gguf).toBeDefined();
    expect(files.filter((f) => f.path.endsWith('Tiny-Q4_K_M.gguf'))).toHaveLength(1);   // a basename collision would make the CLI and the app differ in Ollama by design
    expect(files.filter((f) => /-0000[12]-of-00002/.test(f.path))).toHaveLength(2);
    expect(files.filter((f) => f.path.startsWith('mmproj-'))).toHaveLength(2);
    expect(files.some((f) => f.path.startsWith('MTP/'))).toBe(true);
    expect(Object.keys(spec.aliases ?? {})).toHaveLength(2);
    const seeded = Object.entries(spec.viewFiles?.ollama ?? {}).filter(([k]) => k.startsWith('.hfhub-registry/'));
    expect(seeded.every(([, v]) => v === '{"missing": true}')).toBe(true);
  });

  it('lmstudio-collision configures only LM Studio and holds the basename pair', () => {
    const spec = readCase('lmstudio-collision');
    expect(spec.views).toEqual(['lmstudio']);
    expect(spec.repos[0]!.snapshots[0]!.files.map((f) => f.path).filter((p) => p.endsWith('Tiny-Q4_K_M.gguf'))).toEqual(['Tiny-Q4_K_M.gguf', 'alt/Tiny-Q4_K_M.gguf']);
  });

  it('a dangling fixture link has no blob behind it; the older snapshot still resolves', async () => {
    const dir = await tempDir();
    const built = await buildCase(dir, readCase('sync-fresh'));
    const snap = path.join(built.hub, 'models--acme--Tiny-GGUF', 'snapshots');
    const link = path.join(snap, 'c2', 'Tiny-Q6_K.gguf');
    expect(lstatSync(link).isSymbolicLink()).toBe(true);
    expect(existsSync(link)).toBe(false);
    expect(existsSync(path.join(snap, 'c1', 'Tiny-Q6_K.gguf'))).toBe(true);
  });

  it('treeListing format: directories, links with @HUB@/@CASE@ substitution, files, and masked state timestamps', async () => {
    const dir = await tempDir();
    const hub = path.join(dir, 'hub');
    const root = path.join(dir, 'view');
    mkdirSync(path.join(root, 'sub'), { recursive: true });
    mkdirSync(hub);
    writeFileSync(path.join(root, 'sub', 'f.txt'), 'abc');
    symlinkSync(path.join(hub, 'blob'), path.join(root, 'sub', 'to-hub'));
    symlinkSync(path.join(dir, 'elsewhere'), path.join(root, 'to-case'));
    const stateText = '{"tombstones": {"k": "2026-10-25T14:03:07"}}';
    writeFileSync(path.join(root, '.hfhub-state.json'), stateText);
    const masked = '{"tombstones": {"k": "@TIME@"}}';
    const sha = (s: string): string => createHash('sha256').update(s).digest('hex');
    expect(treeListing(root, hub, dir)).toBe([
      `.hfhub-state.json\tF\t${masked.length}\t${sha(masked)}`,
      'sub\tD',
      `sub/f.txt\tF\t3\t${sha('abc')}`,
      'sub/to-hub\tL\t@HUB@/blob',
      'to-case\tL\t@CASE@/elsewhere',
    ].join('\n') + '\n');
    expect(maskedState(root)).toBe(masked);
    expect(maskedState(path.join(dir, 'sub-none'))).toBe('');
    expect(readlinkSync(path.join(root, 'to-case'))).toBe(path.join(dir, 'elsewhere'));
  });

  it('maskedState rethrows an unexpected read error', async () => {
    const dir = await tempDir();
    mkdirSync(path.join(dir, '.hfhub-state.json'));
    expect(() => maskedState(dir)).toThrow(/EISDIR/);
  });
});
